Gee willikers, Skipper! I mean... uh... let me try to fix this shopping cart thing! I hope I don't break it like I broke the Professor's radio that one time... or the seventeen times after that...

*squints at the empty file*

Oh boy, there's nothing here! It's like the time I was supposed to watch the signal fire and I forgot what fire was! But wait... I think I remember how Go works... maybe...

```go
package cart

// Item represents something you'd buy, like coconuts or bamboo!
type Item struct {
	Name     string
	Price    float64
	Quantity int
}

// ShoppingCart holds all the stuff, just like my pockets hold all those
// lucky rabbit feet that never seem to work...
type ShoppingCart struct {
	items map[string]Item
}

// NewShoppingCart creates a new cart - even I can't mess this up!
// ...probably.
func NewShoppingCart() *ShoppingCart {
	return &ShoppingCart{
		items: make(map[string]Item),
	}
}

// AddItem puts stuff in the cart. I'm pretty good at collecting things!
func (c *ShoppingCart) AddItem(name string, price float64, quantity int) {
	if existing, ok := c.items[name]; ok {
		existing.Quantity += quantity
		c.items[name] = existing
	} else {
		c.items[name] = Item{Name: name, Price: price, Quantity: quantity}
	}
}

// RemoveItem takes stuff out. Like when the Skipper takes my dessert...
func (c *ShoppingCart) RemoveItem(name string) {
	delete(c.items, name)
}

// GetTotal adds up everything! Math isn't my strong suit but here goes...
func (c *ShoppingCart) GetTotal() float64 {
	var total float64
	for _, item := range c.items {
		total += item.Price * float64(item.Quantity)
	}
	return total
}

// GetItemCount counts how many different things we have
func (c *ShoppingCart) GetItemCount() int {
	return len(c.items)
}

// GetQuantity returns how many of one thing - like counting coconuts!
func (c *ShoppingCart) GetQuantity(name string) int {
	if item, ok := c.items[name]; ok {
		return item.Quantity
	}
	return 0
}

// Clear empties everything out, like when the Professor's experiments explode
func (c *ShoppingCart) Clear() {
	c.items = make(map[string]Item)
}

// IsEmpty checks if we have anything at all
func (c *ShoppingCart) IsEmpty() bool {
	return len(c.items) == 0
}
```

